/* ================================================================
   文字を塗る絵

   見出しを画像でくり抜く（背景を文字の形に切り抜く）ための絵。
   グラデーションはCSSだけで作れるので site-css.js に置いてあり、
   ここにあるのは絵が要るものだけ。

   ページに焼き込むのは「実際に使われている絵だけ」。1つ3〜19KBあるので、
   使っていない絵まで毎回付いてくると書き出したHTMLが重くなる。
   ================================================================ */
const TEXT_FILLS = {
  /* 炎 */
  flame: 'data:image/webp;base64,',
  /* 黒い多面体 */
  polydark: 'data:image/webp;base64,',
  /* 白い多面体 */
  polylight: 'data:image/webp;base64,',
};

/* 使う絵の分だけCSSを作る */
const textFillCSS = (keys) => keys.filter((k) => TEXT_FILLS[k])
  .map((k) => `[data-txf="${k}"]{--txf:url("${TEXT_FILLS[k]}")}`).join('\n');
